node - <<'NODE'
const fs = require('fs');
const { chromium } = require('playwright');

(async () => {
  const outPath = '/app/output/final_poster.png';
  const htmlPath = 'file:///app/output/final_poster.html';

  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 2480, height: 3508 }, deviceScaleFactor: 1 });
  await page.goto(htmlPath, { waitUntil: 'networkidle' });

  // Ensure fonts are ready and layout is stable
  await page.evaluate(async () => {
    if (document.fonts && document.fonts.ready) await document.fonts.ready;
  });
  await page.waitForTimeout(250);

  const poster = await page.$('.poster');
  if (!poster) throw new Error('Poster element not found');
  await poster.screenshot({ path: outPath, type: 'png' });

  await browser.close();

  const stat = fs.statSync(outPath);
  console.log('Wrote', outPath, stat.size, 'bytes');
})();
NODE

